"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1754],{46326:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ShredderServer","desc":"Authoritative server script that owns the Workbench Shredder flow for\\nEndless Journey.\\n\\nOn `ReqShredderStart` the server validates workbench proximity, per-player\\ncooldown, and junk availability, then returns a hold duration computed by\\n`ShredderMath`. On `ReqShredderComplete` it re-validates proximity and\\ntiming (anti-exploit: elapsed \u2265 duration \u2212 tolerance), consumes all\\nnon-Energy junk Tools from the player\'s Backpack and equipped slot, computes\\nthe Wood/Metal yield via `JunkConfig.MaterialRules`, and spawns the outputs.\\n\\nMaterial output follows a two-path strategy: up to `MAX_ANIMATED_EJECT_ITEMS`\\npieces fly a `MotionMaster.SplineMove` arc from the workbench spawn point to\\na scatter-disk landing zone, where they register with `ProximityPickupServer`\\nfor nearby collection; overflow pieces are granted directly to the Backpack in\\nyield-sized batches. An auto-collect loop reclaims any unclaimed arc pieces\\nafter `AUTO_COLLECT_DELAY` seconds so materials never pile up indefinitely.","realm":["Server"],"source":{"line":39,"path":"src/ServerScriptService/ShredderServer.server.luau"}}')}}]);